        _PROJECTION_PARAMETERS = projectionParameters ?? PROJECTION_PARAMETERS,
        _PAYLOAD_CODEC = payloadCodec ?? PAYLOAD_CODEC,
        _PAYLOAD = PAYLOAD,
        _PAYLOAD_CID = payloadCid ?? PAYLOAD_CID,
        _PAYLOAD_SHA256 = payloadSha256 ?? PAYLOAD_SHA256,
        _PAYLOAD_SIZE_BYTES = payloadSizeBytes ?? PAYLOAD_SIZE_BYTES,
        _PROVENANCE = PROVENANCE,
        _DESCRIPTION = DESCRIPTION;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? IDOffset = _ID == null ? null
        : fbBuilder.writeString(_ID!);
    final int? EPOCHOffset = _EPOCH == null ? null
        : fbBuilder.writeString(_EPOCH!);
    final int? VALID_STARTOffset = _VALID_START == null ? null
        : fbBuilder.writeString(_VALID_START!);
    final int? VALID_ENDOffset = _VALID_END == null ? null
        : fbBuilder.writeString(_VALID_END!);
    final int? FORECAST_REFERENCE_TIMEOffset = _FORECAST_REFERENCE_TIME == null ? null
        : fbBuilder.writeString(_FORECAST_REFERENCE_TIME!);
    final int? UNITSOffset = _UNITS == null ? null
        : fbBuilder.writeString(_UNITS!);
    final int? CATEGORY_LABELSOffset = _CATEGORY_LABELS == null ? null
        : fbBuilder.writeList(_CATEGORY_LABELS!.map(fbBuilder.writeString).toList());
    final int? PROJECTION_PARAMETERSOffset = _PROJECTION_PARAMETERS?.getOrCreateOffset(fbBuilder);
    final int? PAYLOADOffset = _PAYLOAD == null ? null
        : fbBuilder.writeListUint8(_PAYLOAD!);
    final int? PAYLOAD_CIDOffset = _PAYLOAD_CID == null ? null
        : fbBuilder.writeString(_PAYLOAD_CID!);
    final int? PAYLOAD_SHA256Offset = _PAYLOAD_SHA256 == null ? null
        : fbBuilder.writeString(_PAYLOAD_SHA256!);
    final int? PROVENANCEOffset = _PROVENANCE?.getOrCreateOffset(fbBuilder);
    final int? DESCRIPTIONOffset = _DESCRIPTION == null ? null
        : fbBuilder.writeString(_DESCRIPTION!);
    fbBuilder.startTable(25);
    fbBuilder.addOffset(0, IDOffset);
    fbBuilder.addOffset(1, EPOCHOffset);
    fbBuilder.addOffset(2, VALID_STARTOffset);
    fbBuilder.addOffset(3, VALID_ENDOffset);
    fbBuilder.addOffset(4, FORECAST_REFERENCE_TIMEOffset);
    fbBuilder.addFloat64(5, _FORECAST_LEAD_S);
    fbBuilder.addInt8(6, _VARIABLE?.value);
    fbBuilder.addOffset(7, UNITSOffset);
    fbBuilder.addOffset(8, CATEGORY_LABELSOffset);
    fbBuilder.addInt8(9, _DTYPE?.value);
    fbBuilder.addFloat64(10, _FILL_VALUE);
    fbBuilder.addFloat64(11, _SCALE_FACTOR);
    fbBuilder.addFloat64(12, _ADD_OFFSET);
    fbBuilder.addUint32(13, _NX);
    fbBuilder.addUint32(14, _NY);
    fbBuilder.addInt8(15, _ROW_ORDER?.value);
    fbBuilder.addInt8(16, _PROJECTION?.value);
    fbBuilder.addOffset(17, PROJECTION_PARAMETERSOffset);
    fbBuilder.addInt8(18, _PAYLOAD_CODEC?.value);
    fbBuilder.addOffset(19, PAYLOADOffset);
    fbBuilder.addOffset(20, PAYLOAD_CIDOffset);
    fbBuilder.addOffset(21, PAYLOAD_SHA256Offset);
    fbBuilder.addUint64(22, _PAYLOAD_SIZE_BYTES);
    fbBuilder.addOffset(23, PROVENANCEOffset);
    fbBuilder.addOffset(24, DESCRIPTIONOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
